function on(sel,event,fn){$(sel)?.addEventListener(event,async e=>{try{await fn(e);}catch(error){toast(error.message);}})}
function modal(html,submit,confirmLabel='Xác nhận'){const d=$('#modal');if(d.open)d.close();d.innerHTML=`<form id="modal-form">${html}<div class="button-row"><button type="button" id="close-modal">Hủy</button><button class="primary">${esc(confirmLabel)}</button></div></form>`;d.showModal();$('#close-modal').onclick=()=>d.close();$('#modal-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await submit(new FormData(e.target));d.close();}catch(err){toast(err.message);}finally{button.disabled=false;}};}

function chooseChapter(storyId){
 const story=[...state.library,...state.myLibrary].find(item=>item.id===storyId);
 return api(`/read/${storyId}`).then(chapters=>{
  if(!chapters.length)throw new Error('Tài liệu này chưa có phần nào để đọc.');
  state.chapters=chapters;state.readerStory={id:storyId,title:story?.title||'',cover:Boolean(story?.cover_key),study:/^study(?:-book)?:/u.test(story?.source_url||'')&&state.myLibrary.some(item=>item.id===storyId)};state.bookDownload=null;localSources=new Map();loadReaderTerms(storyId);
  modal(`<div class="chapter-choice-heading"><p class="eyebrow">${esc(story?.title||'MỤC LỤC')}</p><h2>Chọn phần bắt đầu</h2><p class="subtitle">${chapters.length} phần đã công bố</p></div><label class="chapter-search">Tìm phần<input id="chapter-search-input" type="search" placeholder="Nhập số hoặc tên phần…" autocomplete="off"></label><label class="chapter-choice-label">Mục lục tài liệu<select name="chapter" id="chapter-start-select" size="${Math.min(9,chapters.length)}" required>${chapters.map((chapter,index)=>`<option value="${index}" ${index===0?'selected':''}>${index+1}. ${esc(chapter.title)}</option>`).join('')}</select></label><p id="chapter-search-empty" class="subtitle" hidden>Không tìm thấy phần phù hợp.</p>`,form=>{openReaderWithBookAnimation(story,Number(form.get('chapter')));},'Mở sách');
  on('#chapter-search-input','input',event=>{const query=normalizeLibraryText(event.target.value),select=$('#chapter-start-select');let visible=0;for(const option of select.options){const matches=normalizeLibraryText(option.textContent).includes(query);option.hidden=!matches;if(matches)visible++;}if(select.selectedOptions[0]?.hidden)select.value=Array.from(select.options).find(option=>!option.hidden)?.value||'';$('#chapter-search-empty').hidden=visible>0;});
 });
}

function openReaderWithBookAnimation(story,chapterIndex){
 state.chapter=chapterIndex;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){go('reader');return;}
 document.querySelector('.book-opening-overlay')?.remove();
 const cover=story?.cover_key?`<img src="/api/covers/${encodeURIComponent(story.id)}?v=${encodeURIComponent(story.cover_key)}" alt="">`:`<div class="opening-cover-placeholder">${esc(story?.title?.slice(0,1)||'書')}</div>`;
 const overlay=document.createElement('div');overlay.className='book-opening-overlay';overlay.setAttribute('aria-hidden','true');overlay.innerHTML=`<div class="opening-light"></div><div class="opening-book"><div class="opening-pages opening-pages-left"><span></span><span></span><span></span></div><div class="opening-pages opening-pages-right"><span></span><span></span><span></span></div><div class="opening-book-cover">${cover}<div class="opening-cover-shade"></div><strong>${esc(story?.title||'Hoa Trí')}</strong></div><div class="opening-book-spine"></div></div><p class="opening-caption">Đang mở · ${esc(state.chapters[chapterIndex]?.title||'Phần tài liệu')}</p>`;document.body.append(overlay);
 requestAnimationFrame(()=>overlay.classList.add('is-opening'));
 setTimeout(()=>{go('reader');overlay.classList.add('is-finished');},1050);
 setTimeout(()=>overlay.remove(),1500);
}
